	private long findLocalReferenceByPartition(int partition, long rawRowId, LookupCursor cursor) {
		int count = partitionShardCounts[partition];
		if (count == 0) {
			return 0;
		}
		if (!cursor.covers(this, partition, rawRowId)) {
			int start = partitionShardStarts[partition];
			int floor = count == 1 ? floorSingleShard(start, rawRowId) : floorShard(partition, start, count, rawRowId);
			if (floor < start) {
				return 0;
			}
			CsfShard shard = shards[floor];
			int localPage = shard.floorPage(rawRowId);
			if (localPage < 0) {
				return 0;
			}
			int globalPage = Math.addExact(shardFirstPageIds[floor], localPage);
			if (cursor.owner != this || cursor.globalPage != globalPage) {
				cursor.pageChanged(this, partition, globalPage, shard.validatedPageAddress(localPage));
			}
		}
		int localRow = cursor.findRowCached(rawRowId);
		if (localRow < 0 || !cursor.reusablePage) {
			return 0;
		}
		return packLocalReference(cursor.globalPage, localRow);
	}

	private long localReferenceAtOrdinal(int partition, long ordinal, OrdinalCursor cursor) {
		long rows = partitionRowCounts[partition];
		if (ordinal < 0 || ordinal >= rows) {
			throw new IllegalArgumentException("row ordinal out of range: " + ordinal + " of " + rows);
		}
		if (cursor != null && cursor.globalPage >= 0 && ordinal >= cursor.firstOrdinal && ordinal < cursor.endOrdinal) {
			return packLocalReference(cursor.globalPage, Math.toIntExact(ordinal - cursor.firstOrdinal));
		}

		int start = partitionShardStarts[partition];
		int end = start + partitionShardCounts[partition];
		int low = start;
		int high = end - 1;
		int shardIndex = -1;
		while (low <= high) {
			int mid = low + high >>> 1;
			if (shardFirstRowOrdinals[mid] <= ordinal) {
				shardIndex = mid;
				low = mid + 1;
			} else {
				high = mid - 1;
			}
		}
		while (shardIndex >= start && shards[shardIndex].rowCount() == 0) {
			shardIndex--;
		}
		if (shardIndex < start) {
			throw new IllegalStateException("row ordinal maps only to continuation shards");
		}
		CsfShard shard = shards[shardIndex];
		long localOrdinal = ordinal - shardFirstRowOrdinals[shardIndex];
		low = 0;
		high = shard.pageCount() - 1;
		int page = -1;
		while (low <= high) {
			int mid = low + high >>> 1;
			if (shard.pageFirstRowOrdinal(mid) <= localOrdinal) {
				page = mid;
				low = mid + 1;
			} else {
				high = mid - 1;
			}
		}
		while (page >= 0 && shard.pageUniqueRows(page) == 0) {
			page--;
		}
		if (page < 0) {
			throw new IllegalStateException("row ordinal maps only to continuation pages");
		}
		long pageFirst = shardFirstRowOrdinals[shardIndex] + shard.pageFirstRowOrdinal(page);
		int uniqueRows = shard.pageUniqueRows(page);
		int localRow = Math.toIntExact(ordinal - pageFirst);
		if (localRow < 0 || localRow >= uniqueRows) {
			throw new IllegalStateException("row ordinal is outside its directory page");
		}
		int globalPage = Math.addExact(shardFirstPageIds[shardIndex], page);
		if (cursor != null) {
			cursor.firstOrdinal = pageFirst;
			cursor.endOrdinal = pageFirst + uniqueRows;
			cursor.globalPage = globalPage;
		}
		return packLocalReference(globalPage, localRow);
	}

	/** Benchmark-only equivalent of the production cursor path, with an exact decoded-page sidecar. */
	long findLocalReference(long predicateOrdinal, int plane, long rawRowId, AcceleratedLookupCursor cursor) {
		Objects.requireNonNull(cursor, "cursor");
		int partition = partitionIndex(predicateOrdinal, plane);
		int count = partitionShardCounts[partition];
		if (count == 0) {
			return 0;
		}
		int floor;
		int localPage;
		if (cursor.covers(this, partition, rawRowId)) {
			floor = cursor.shard;
			localPage = cursor.localPage;
		} else {
			int start = partitionShardStarts[partition];
			floor = count == 1 ? floorSingleShard(start, rawRowId) : floorShard(partition, start, count, rawRowId);
			if (floor < start) {
				return 0;
			}
			CsfShard shard = shards[floor];
			localPage = shard.floorPage(rawRowId);
			if (localPage < 0) {
				return 0;
			}
			if (cursor.owner != this || cursor.shard != floor || cursor.localPage != localPage) {
				shard.page(localPage, cursor);
				cursor.pageChanged(this, partition, floor, localPage);
			}
		}
		CompactCsfPageReader page = cursor;
		int localRow = cursor.findRowCached(rawRowId);
		if (localRow < 0 || page.continuation()) {
			return 0;
		}
		int globalPage = Math.addExact(shardFirstPageIds[floor], localPage);
		return packLocalReference(globalPage, localRow);
	}

	public long packHandle(long localReference) {
		if (localReference <= 0 || localReference > MAX_LOCAL_REFERENCE) {
			throw new IllegalArgumentException("invalid CSF local reference: " + localReference);
		}
		return (long) HANDLE_SLOT << 40 | localReference;
	}

	public static boolean isHandle(long handle) {
		return handle > 0 && handle >>> 48 == 0 && (int) (handle >>> 40) == HANDLE_SLOT;
	}

	public static long localReference(long handle) {
		if (!isHandle(handle)) {
			throw new IllegalArgumentException("not a CSF run handle: " + handle);
		}
		return handle & MAX_LOCAL_REFERENCE;
	}

